"use client";

import { useState, useEffect } from "react";
import { logApiUrl } from "@/lib/constants";
import { resolvePublicApiUrl } from "@/lib/publicApiUrl";

const STORAGE_KEY = "article-font-size";
const MIN_LEVEL = 0;
const MAX_LEVEL = 2;

const VIEW_INCREMENT_STORAGE_PREFIX = "article-view-incremented";

/**
 * Solo `Accept`: gli header server-side (User-Agent, Referer) sono vietati dal
 * browser e verrebbero comunque scartati. Tenendo la richiesta "semplice"
 * evitiamo il preflight CORS quando `NEXT_PUBLIC_TJ_API_BASE_URL` punta a tj-api.
 */
const VIEW_REQUEST_HEADERS: Record<string, string> = { Accept: "application/json" };

/** Conteggio views: tj-api restituisce `views`, il fallback WP `count`/`post_views`. */
function parseViewsPayload(data: unknown): number | null {
  if (!data || typeof data !== "object") return null;
  const o = data as Record<string, unknown>;
  for (const key of ["views", "count", "post_views"] as const) {
    const raw = o[key];
    if (raw == null) continue;
    const n = typeof raw === "number" ? raw : Number(raw);
    if (Number.isFinite(n) && n >= 0) return n;
  }
  return null;
}

/** sessionStorage può lanciare (Safari in navigazione privata): mai far cadere l'effect. */
function hasIncrementedInSession(key: string): boolean {
  try {
    return sessionStorage.getItem(key) === "1";
  } catch {
    return false;
  }
}

function markIncrementedInSession(key: string): void {
  try {
    sessionStorage.setItem(key, "1");
  } catch {
    // storage non disponibile: al massimo si re-incrementa al prossimo mount
  }
}

interface ArticleBodyProps {
  /**
   * HTML **già sanificato** lato server da `enrichArticle`.
   *
   * Il nome della prop è la garanzia richiesta al chiamante, e il motivo per cui
   * si chiama così: prima questo componente invocava `sanitizeRichHtml` in un
   * `useMemo`, il che significava spedire `sanitize-html` nel bundle client di
   * ogni pagina articolo per ri-sanificare, a ogni idratazione, HTML che il
   * server aveva già sanificato per produrre lo stesso markup.
   *
   * Un nome neutro come `html` avrebbe reso invisibile la precondizione nei
   * punti di chiamata; con `safeHtml` chi passa contenuto grezzo se ne accorge
   * leggendo la propria riga di codice.
   */
  safeHtml: string;
  viewCount?: number | null;
  postId?: number;
}

export default function ArticleBody({ safeHtml, viewCount: viewCountProp, postId }: ArticleBodyProps) {
  const [level, setLevel] = useState(1);
  const [viewCountFetched, setViewCountFetched] = useState<number | null>(null);
  // Dopo la migrazione su Postgres, viewCount SSR da WP è spesso 0: preferire il conteggio live da /api/views.
  const viewCount =
    viewCountFetched != null
      ? viewCountFetched
      : viewCountProp != null && viewCountProp > 0
        ? viewCountProp
        : viewCountFetched;

  useEffect(() => {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored !== null) {
        const n = parseInt(stored, 10);
        if (n >= MIN_LEVEL && n <= MAX_LEVEL) {
          const timer = window.setTimeout(() => setLevel(n), 0);
          return () => window.clearTimeout(timer);
        }
      }
    } catch {
      // ignore
    }
  }, []);

  /**
   * Una sola richiesta per mount.
   *
   * Il POST incrementa *e* restituisce il conteggio aggiornato, quindi alla prima
   * lettura in sessione una GET separata sarebbe una seconda invocation per lo
   * stesso dato. La GET serve solo a chi rilegge l'articolo nella stessa sessione,
   * dove il POST è già stato fatto (il `viewCount` SSR da WP resta inaffidabile,
   * vedi nota sopra).
   */
  useEffect(() => {
    if (!postId || typeof window === "undefined") return;

    const key = `${VIEW_INCREMENT_STORAGE_PREFIX}:${postId}`;
    const alreadyIncremented = hasIncrementedInSession(key);
    const url = resolvePublicApiUrl(`/api/views/${postId}`);
    const ctrl = new AbortController();
    logApiUrl(url);

    void (async () => {
      try {
        const res = await fetch(url, {
          method: alreadyIncremented ? "GET" : "POST",
          headers: VIEW_REQUEST_HEADERS,
          signal: ctrl.signal,
          ...(alreadyIncremented ? {} : { keepalive: true }),
        });
        if (!res.ok) return;
        const views = parseViewsPayload(await res.json());
        if (views == null) return;
        setViewCountFetched(views);
        if (!alreadyIncremented) markIncrementedInSession(key);
      } catch {
        // rete/abort: si tiene il conteggio SSR, nessun retry (costa un'invocation)
      }
    })();

    return () => ctrl.abort();
  }, [postId]);

  const persist = (value: number) => {
    setLevel(value);
    try {
      localStorage.setItem(STORAGE_KEY, String(value));
    } catch {
      // ignore
    }
  };

  const smaller = () => persist(Math.max(MIN_LEVEL, level - 1));
  const larger = () => persist(Math.min(MAX_LEVEL, level + 1));

  return (
    <div className="article-body-wrapper" data-font-size={level}>
      <div className="flex items-center justify-between gap-4 mb-4">
        <div className="flex items-center gap-2 text-muted text-sm" title="Numero di letture dell’articolo">
          <svg className="w-4 h-4 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden>
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
          </svg>
          <span aria-label="Visualizzazioni">
            {viewCount != null ? viewCount.toLocaleString("it-IT") : "—"}
          </span>
        </div>
        <div className="flex items-center gap-2">
          <span className="text-muted text-sm mr-1">Testo:</span>
          <button
            type="button"
            onClick={smaller}
            disabled={level === MIN_LEVEL}
            className="w-11 h-11 rounded border border-border bg-surface-overlay text-foreground hover:bg-surface-overlay-strong disabled:opacity-40 disabled:cursor-not-allowed flex items-center justify-center text-sm font-bold transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent"
            aria-label="Riduci dimensione testo"
          >
            A−
          </button>
          <button
            type="button"
            onClick={larger}
            disabled={level === MAX_LEVEL}
            className="w-11 h-11 rounded border border-border bg-surface-overlay text-foreground hover:bg-surface-overlay-strong disabled:opacity-40 disabled:cursor-not-allowed flex items-center justify-center text-sm font-bold transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent"
            aria-label="Aumenta dimensione testo"
          >
            A+
          </button>
        </div>
      </div>
      <div
        className="article-content"
        dangerouslySetInnerHTML={{ __html: safeHtml }}
      />
    </div>
  );
}
